'use strict';
const currencyFormatter=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});
const $=s=>document.querySelector(s),money=n=>currencyFormatter.format(n/100);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=()=>iso(new Date());
const human=s=>s.split('-').reverse().join('/');
const frequencies={once:'Única vez',weekly:'Semanal',fortnightly:'A cada 15 dias',monthly:'Mensal',yearly:'Anual'};
let refreshVersion=0,saving=false;
let state={entries:[],goals:[]},report,monthReport,view='dashboard',period='month',anchor=new Date(),demo=false,filter='',customRange=null;
async function api(path,body){return webApi(path,body)}
function range(type=period,date=anchor){let a=new Date(date.getFullYear(),date.getMonth(),date.getDate()),b;if(type==='custom'&&customRange)return [...customRange];if(type==='day')b=new Date(a);else if(type==='month'){a.setDate(1);b=new Date(a.getFullYear(),a.getMonth()+1,0)}else if(type==='year'){a=new Date(a.getFullYear(),0,1);b=new Date(a.getFullYear(),11,31)}else{a.setDate(a.getDate()-((a.getDay()+6)%7));b=new Date(a);b.setDate(b.getDate()+6)}return[iso(a),iso(b)]}
async function getReport(type=period,date=anchor){const[a,b]=range(type,date);return api(`/api/report?start=${a}&end=${b}`)}
async function refresh(){const version=++refreshVersion,current=getReport(),sameMonth=range().join()===range('month',new Date()).join();const result=await Promise.all([current,sameMonth?current:getReport('month',new Date())]);if(version!==refreshVersion)return;[report,monthReport]=result;render()}
async function save(next){if(saving)throw Error('Aguarde o salvamento em andamento.');saving=true;const profile=GoogleProfiles.store.active,epoch=GoogleProfiles.store.epoch;try{await api('/api/state',next);if(profile!==GoogleProfiles.store.active||epoch!==GoogleProfiles.store.epoch)throw Error('O perfil mudou. Os dados foram preservados no perfil de origem.');state=next;demo=!!state.demo;await refresh();toast(GoogleProfiles.store.current()?'Salvo neste navegador. Consulte o status do envio ao Drive.':'Alterações salvas no perfil local.')}finally{saving=false}}
function toast(text){const dialog=document.querySelector('dialog[open]');if(dialog){let message=dialog.querySelector('.form-message');if(!message){message=document.createElement('p');message.className='form-message notice';message.setAttribute('role','alert');(dialog.querySelector('form')||dialog).append(message)}message.textContent=text}$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200)}
function safe(fn){return async(...args)=>{try{await fn(...args)}catch(e){toast(e.message)}}}
const meta={sheet:['PLANILHA DE GASTOS','Planilha de gastos','Confira as despesas do período em linhas e colunas.'],categories:['CATEGORIAS','Categorias','Organize seus lançamentos com símbolos e cores.'],profiles:['PERFIS E GOOGLE DRIVE','Perfis e Google Drive','Entre com Google para separar seus dados e salvar cópias no Drive.'],incomeSources:['FONTES DE RECEITA','Fontes de receita','Cadastre e organize as origens das suas receitas.'],accounts:['CONTAS E CARTÕES','Contas e cartões','Cadastre as contas e os cartões usados nos lançamentos.'],dashboard:['VISÃO GERAL','Visão geral','Receitas, despesas e saldo do período.'],entries:['LANÇAMENTOS','Lançamentos','Cadastre e consulte receitas e despesas.'],goals:['METAS','Metas','Defina valores, prazos e quanto guardar por mês.'],reports:['RELATÓRIOS','Relatórios','Consulte e exporte os dados do período.'],settings:['CONFIGURAÇÕES','Configurações','Backup, restauração e armazenamento dos dados.']};
function render(){const profileInfo=GoogleProfiles.stateInfo(),m=meta[view];$('#breadcrumb').textContent=m[0];$('#heading').textContent=m[1];$('#subtitle').textContent=m[2];$('.toolbar').classList.toggle('hidden',['settings','goals','accounts','incomeSources','profiles','categories'].includes(view));$('#new-entry').classList.toggle('hidden',['settings','profiles','categories'].includes(view));$('#new-entry').textContent=view==='incomeSources'?'+ Nova fonte de receita':view==='accounts'?'+ Nova conta ou cartão':view==='goals'?'+ Nova meta':'+ Novo lançamento';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelectorAll('[data-period]').forEach(b=>b.classList.toggle('selected',b.dataset.period===period));const[a,b]=range();$('#period-label').textContent=period==='month'?anchor.toLocaleDateString('pt-BR',{month:'long',year:'numeric'}):period==='year'?String(anchor.getFullYear()):period==='day'?human(a):`${human(a).slice(0,5)} — ${human(b)}`;$('#custom-period').hidden=period!=='custom';$('#period-date').parentElement.hidden=period==='custom';$('#period-date').value=iso(anchor);$('#prev').disabled=$('#next').disabled=period==='custom';$('#demo-label').classList.toggle('hidden',!demo);$('#content').innerHTML=({sheet:expenseSheet,categories:categories,profiles:()=>profiles(profileInfo),incomeSources:incomeSources,accounts:accounts,dashboard:dashboard,entries:entries,goals:goals,reports:reports,settings:settings}[view])();renderProfileStatus(profileInfo);}
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();view='dashboard';render();});
function stat(label,value,icon,note,highlight=false){return `<div class="stat ${highlight?'highlight':''}"><div class="stat-top">${label}<span class="stat-icon">${icon}</span></div><strong>${money(value)}</strong><small>${note}</small></div>`}
function categoryTotals(){const groups=Object.create(null);for(const o of report.occurrences)if(o.entry.kind==='expense')groups[o.entry.category]=(groups[o.entry.category]||0)+o.entry.cents;return Object.entries(groups).sort((a,b)=>b[1]-a[1]);}
function categoryChart(){const groups=categoryTotals();if(groups.length>5){const rest=groups.splice(5);groups.push(['Demais categorias',rest.reduce((sum,item)=>sum+item[1],0)])}if(!groups.length)return '<div class="empty">Suas despesas por categoria aparecerão aqui.</div>';return groups.map(([name,value])=>`<div class="category-row"><div class="category-label"><span>${categoryBadge(name)}</span><span>${money(value)}</span></div><div class="track"><div class="fill" style="background:${Categories.appearance(state,name).color};width:${100*value/report.expense}%"></div></div></div>`).join('')+`<div class="category-total"><span>Total de despesas previstas</span><b>${money(report.expense)}</b></div>`;}
function goalCard(g,controls=false){const p=report.plans.find(p=>p.id===g.id),percent=Math.round(g.saved/g.target*100);return `<div class="goal-item"><div class="goal-top"><span class="goal-icon">${/carro/i.test(g.name)?'↗':'⚑'}</span><div><h3>${esc(g.name)}</h3><small>Até ${human(g.deadline)} ${p?.overdue?'· Prazo vencido':''}</small></div><span class="goal-percent">${percent}%</span></div><div class="track"><div class="fill" style="width:${percent}%"></div></div><div class="goal-values"><b>${money(g.saved)}</b><span>de ${money(g.target)}</span></div>${controls?`<p class="muted">Guardar ${money(p?.monthly||0)} por mês${p?.overdue?' · Reavalie o prazo':''}</p><div class="actions"><button data-edit-goal="${esc(g.id)}">Editar</button><button data-delete-goal="${esc(g.id)}">Excluir</button></div>`:''}</div>`;}
function insight(){if(!state.goals.length)return 'Cadastre uma meta para descobrir quanto reservar por mês e acompanhar seu avanço.';const need=monthReport.monthly_required,free=monthReport.balance,gap=Math.max(0,need-free);if(!gap)return `Sua previsão do mês atual comporta ${money(need)} para as metas. Após essa reserva, restam ${money(free-need)}. Valores sem rendimentos e sujeitos aos gastos não cadastrados.`;const flexible=Object.create(null);for(const o of monthReport.occurrences)if(o.entry.kind==='expense'&&['Lazer','Alimentação','Outros'].includes(o.entry.category))flexible[o.entry.category]=(flexible[o.entry.category]||0)+o.entry.cents;const total=Object.values(flexible).reduce((a,b)=>a+b,0);return `Suas metas pedem ${money(need)}/mês. No mês atual, faltam ${money(gap)} após os gastos previstos. ${total>=gap?`Simulação: reduzir ${Math.ceil(gap/total*100)}% em ${Object.keys(flexible).map(esc).join(', ')} cobriria essa diferença.`:'Considere ampliar o prazo, reduzir gastos ajustáveis ou aumentar a renda.'} Nenhuma alteração é feita automaticamente.`;}
const PAGE_SIZE=100;
let tablePageIndex=0,tablePageKey='',sheetPageIndex=0,sheetPageKey='';
function pagination(page,count,kind){if(count<=PAGE_SIZE)return '';const pages=Math.ceil(count/PAGE_SIZE);return `<div class="table-pages"><span role="status">${page*PAGE_SIZE+1}–${Math.min((page+1)*PAGE_SIZE,count)} de ${count} · Página ${page+1} de ${pages}</span><button class="secondary" data-${kind}-page="${page-1}" ${page===0?'disabled':''}>Anterior</button><button class="secondary" data-${kind}-page="${page+1}" ${page+1>=pages?'disabled':''}>Próxima</button></div>`;}
function rows(items,actions=false){const count=items.length,key=JSON.stringify([view,range(),filter,typeof reportKind==='undefined'?'':reportKind,typeof reportSource==='undefined'?'':reportSource,count,items[0]?.entry.id,items[count-1]?.entry.id]);if(key!==tablePageKey){tablePageIndex=0;tablePageKey=key;}tablePageIndex=Math.max(0,Math.min(tablePageIndex,Math.ceil(count/PAGE_SIZE)-1));items=items.slice(tablePageIndex*PAGE_SIZE,(tablePageIndex+1)*PAGE_SIZE);if(!items.length)return '<div class="empty">Nenhum lançamento neste período.</div>';return `<div class="table-wrap"><table><thead><tr><th>Descrição / conta</th><th>Categoria</th><th>Data</th><th class="amount">Valor</th>${actions?'<th>Ações</th>':''}</tr></thead><tbody>${items.map(o=>`<tr><td>${esc(o.entry.description)}<small>${o.entry.kind==='income'?'Origem: ':'Conta/cartão: '}${esc(o.entry.source)}${o.entry.kind==='income'&&o.entry.account?' · Recebido em: '+esc(o.entry.account):''} · ${frequencies[o.entry.frequency]}</small></td><td>${categoryBadge(o.entry.category)}</td><td>${human(o.date)}</td><td class="amount ${o.entry.kind}">${o.entry.kind==='income'?'+':'−'} ${money(o.entry.cents)}</td>${actions?`<td><div class="actions"><button data-edit-entry="${esc(o.entry.id)}">Editar</button><button data-delete-entry="${esc(o.entry.id)}">Excluir</button></div></td>`:''}</tr>`).join('')}</tbody></table></div>${pagination(tablePageIndex,count,'table')}`;}
function dashboard(){const required=report.monthly_required,rate=report.income>0?Math.round(report.balance/report.income*100):0;return `<section class="stats">${stat('Receitas previstas',report.income,'↙','No período selecionado')}${stat('Despesas previstas',report.expense,'↗','Inclui recorrências cadastradas')}${stat('Saldo previsto',report.balance,'◈',`${rate}% das receitas do período`,true)}${stat('Reserva para metas / mês',required,'⚑',`${state.goals.length} meta(s) · referência: mês atual`)}</section><p class="overview-note">Projeção pelos lançamentos cadastrados. Não representa saldo bancário ou confirmação de pagamento.</p>${state.entries.length?'':`<div class="card empty full-card"><h2>Nenhum lançamento cadastrado</h2><p>Adicione uma receita ou despesa para começar.</p><button class="primary" data-action="new-entry">Cadastrar lançamento</button><button class="secondary" data-action="demo">Carregar dados de exemplo</button></div>`}${expenseSummary()}<div class="grid"><section class="card"><div class="card-head"><div><h2>Despesas por categoria</h2><p>Distribuição das despesas no período</p></div><span class="tag">POR CATEGORIA</span></div>${categoryChart()}</section><section class="card"><div class="card-head"><div><h2>Metas</h2><p>Valores guardados e prazos</p></div><button class="text-btn" data-action="goals">Ver metas ↗</button></div>${state.goals.slice(0,2).map(g=>goalCard(g)).join('')||'<div class="empty">Nenhuma meta cadastrada.<br><button class="text-btn" data-action="new-goal">+ Criar uma meta</button></div>'}<div class="insight"><span class="spark">✧</span><div><h3>Plano de economia</h3><p>${insight()}</p></div></div></section></div><section class="card full-card"><div class="card-head"><h2>Lançamentos do período</h2><button class="text-btn" data-action="entries">Ver todos</button></div>${rows(report.occurrences.slice(-4).reverse())}</section>`;}
function entries(){const matching=report.occurrences.filter(o=>`${o.entry.description} ${o.entry.category} ${o.entry.source} ${o.entry.account||''}`.toLocaleLowerCase().includes(filter.toLocaleLowerCase()));return `<div class="card"><div class="card-head"><div><h2>Lançamentos previstos</h2><p>Recorrências: editar afeta toda a série. Parcelas: editar afeta somente a parcela selecionada.</p></div><input class="search" id="search" placeholder="Buscar descrição, categoria, origem ou conta" value="${esc(filter)}" aria-label="Buscar lançamentos"></div>${rows(matching,true)}</div>`;}
let sheetSource='',sheetCategory='',sheetSearch='';
function expenseSheet(){
 const sourceNames=[...new Set(report.occurrences.filter(o=>o.entry.kind==='expense').map(o=>o.entry.source))].sort((a,b)=>a.localeCompare(b,'pt-BR'));
 const categoryNames=[...new Set(report.occurrences.filter(o=>o.entry.kind==='expense').map(o=>o.entry.category))].sort((a,b)=>a.localeCompare(b,'pt-BR'));
 const matching=report.occurrences.filter(o=>o.entry.kind==='expense'&&(!sheetSource||o.entry.source===sheetSource)&&(!sheetCategory||o.entry.category===sheetCategory)&&o.entry.description.toLocaleLowerCase('pt-BR').includes(sheetSearch.toLocaleLowerCase('pt-BR'))).slice().sort((a,b)=>a.date.localeCompare(b.date)||a.entry.description.localeCompare(b.entry.description,'pt-BR'));
 const grandTotal=matching.reduce((sum,o)=>sum+o.entry.cents,0),pageKey=JSON.stringify([range(),sheetSource,sheetCategory,sheetSearch]);if(pageKey!==sheetPageKey){sheetPageIndex=0;sheetPageKey=pageKey;}sheetPageIndex=Math.max(0,Math.min(sheetPageIndex,Math.ceil(matching.length/PAGE_SIZE)-1));const start=sheetPageIndex*PAGE_SIZE,visible=matching.slice(start,start+PAGE_SIZE);let total=matching.slice(0,start).reduce((sum,o)=>sum+o.entry.cents,0);
 const options=(values,selected)=>values.map(value=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(value)}</option>`).join('');
 return `<section class="card sheet-card"><div class="card-head"><div><h2>Despesas em exibição</h2><p>${human(range()[0])} a ${human(range()[1])} · ${matching.length} lançamento(s)</p></div><strong class="sheet-total">${money(grandTotal)}</strong></div><div class="sheet-filters"><label>Fonte<select id="sheet-source"><option value="">Todas as fontes</option>${options([...new Set([...sourceNames,...(sheetSource?[sheetSource]:[])])],sheetSource)}</select></label><label>Categoria<select id="sheet-category"><option value="">Todas as categorias</option>${options([...new Set([...categoryNames,...(sheetCategory?[sheetCategory]:[])])],sheetCategory)}</select></label><label>Descrição<input id="sheet-search" type="search" value="${esc(sheetSearch)}" placeholder="Buscar despesa"></label><button class="secondary" data-sheet-clear>Limpar filtros</button></div><div class="sheet-scroll" tabindex="0" aria-label="Planilha de despesas, role para ver todas as colunas"><table class="expense-sheet"><caption>Despesas previstas no período selecionado</caption><thead><tr><th scope="col">#</th><th scope="col">Data</th><th scope="col">Descrição</th><th scope="col">Fonte / conta ou cartão</th><th scope="col">Categoria</th><th scope="col">Recorrência</th><th scope="col" class="amount">Valor</th><th scope="col" class="amount">Acumulado</th></tr></thead><tbody>${visible.map((o,i)=>{total+=o.entry.cents;return `<tr><th scope="row">${start+i+1}</th><td>${human(o.date)}</td><td>${esc(o.entry.description)}</td><td>${esc(o.entry.source)}</td><td>${categoryBadge(o.entry.category)}</td><td>${esc(frequencies[o.entry.frequency]||o.entry.frequency)}</td><td class="amount">${money(o.entry.cents)}</td><td class="amount">${money(total)}</td></tr>`;}).join('')||'<tr><td colspan="8" class="empty">Nenhuma despesa corresponde ao período e aos filtros selecionados.</td></tr>'}</tbody><tfoot><tr><th colspan="6" scope="row">Total das despesas em exibição</th><td class="amount" data-sheet-total>${money(grandTotal)}</td><td class="amount">${money(grandTotal)}</td></tr></tfoot></table></div>${pagination(sheetPageIndex,matching.length,'sheet')}<p class="muted">Prévia para consulta. Inclui as ocorrências das despesas recorrentes e as parcelas cadastradas, conforme suas datas. Não confirma pagamento. Para alterar um registro, abra Lançamentos.</p></section>`;
}
$('#period-date').addEventListener('change',safe(async e=>{if(!e.target.validity.valid||!e.target.value)return;anchor=new Date(e.target.value+'T12:00:00');await refresh();}));
$('#custom-period').addEventListener('submit',safe(async e=>{e.preventDefault();const f=e.target,a=f.elements.start.value,b=f.elements.end.value;if(!a||!b||a>b)throw Error('Escolha uma data final igual ou posterior à inicial.');if((Date.parse(b)-Date.parse(a))/86400000>365)throw Error('Escolha um intervalo de até 366 dias.');customRange=[a,b];await refresh();}));
document.addEventListener('change',e=>{if(e.target.id==='sheet-source'){sheetSource=e.target.value;render();}if(e.target.id==='sheet-category'){sheetCategory=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id!=='sheet-search')return;sheetSearch=e.target.value;const pos=e.target.selectionStart;render();const input=$('#sheet-search');input.focus();input.setSelectionRange(pos,pos);});
document.addEventListener('click',e=>{const page=e.target.closest('[data-table-page],[data-sheet-page]');if(page){if(page.hasAttribute('data-table-page'))tablePageIndex=Number(page.dataset.tablePage);else sheetPageIndex=Number(page.dataset.sheetPage);render();return;}if(e.target.closest('[data-sheet-clear]')){sheetSource=sheetCategory=sheetSearch='';render();}});
function goals(){return `<div class="card"><div class="card-head"><div><h2>Metas</h2><p>Plano sem rendimentos, dividido do mês atual até o mês do prazo.</p></div><button class="primary" data-action="new-goal">+ Nova meta</button></div>${state.goals.map(g=>goalCard(g,true)).join('')||'<div class="empty">Adicione uma meta para começar.</div>'}</div><div class="insight"><span class="spark">✧</span><div><h3>Capacidade de poupança · mês atual</h3><p>${insight()}</p></div></div>`;}
function reports(){return `<section class="card"><div class="card-head"><div><h2>Relatório do período</h2><p>Use o seletor acima para consultar semana, mês ou ano.</p></div><button class="primary" data-action="csv">↓ Exportar CSV</button></div><div class="notice">Relatório de controle pessoal com projeções, incluindo recorrências. Não é um demonstrativo fiscal. Exportação PDF e campos de comprovantes serão adicionados em outra etapa.</div><div class="report-summary"><div>Receitas<b>${money(report.income)}</b></div><div>Despesas<b>${money(report.expense)}</b></div><div>Saldo previsto<b>${money(report.balance)}</b></div></div><div style="margin-top:28px">${rows(report.occurrences)}</div></section>`;}
function settings(){return `<div class="card settings-block"><h2>Dados e cópias de segurança</h2><p>Os dados exibidos pertencem ao perfil atual. A cópia JSON contém somente os dados deste perfil e não contém credenciais Google.</p><button class="secondary" data-action="backup">↓ Baixar cópia JSON</button><button class="secondary" data-action="restore">↑ Restaurar cópia JSON</button><hr><h2>Google Drive</h2><p>Consulte a conexão, a data do último envio confirmado e as cópias anteriores em Perfis e Google Drive.</p><button class="secondary" data-view="profiles">Abrir perfis e Google Drive</button><hr><h2>Dados de exemplo</h2><p>A demonstração adiciona lançamentos fictícios somente a uma base vazia.</p><button class="secondary" data-action="demo">Carregar demonstração</button><button class="secondary remove-demo" data-action="clear-demo" ${demo?'':'disabled'}>Remover demonstração</button></div>`;}
function openEntry(id){const f=$('#entry-form');f.querySelector('.form-message')?.remove();f.reset();MoneyInput.reset(f);f.elements.id.value='';f.elements.date.value=today();if(id){const e=state.entries.find(e=>e.id===id);for(const k of ['id','description','kind','category','source','date','frequency'])f.elements[k].value=e[k];f.elements.amount.value=MoneyInput.format(e.cents);f.elements.end_date.value=e.end_date||''}f.elements.account.value=id?(state.entries.find(e=>e.id===id).account||''):'';updateAccountOptions();updateIncomeSourceOptions();updateCategoryOptions();updateEntryFields();$('#entry-title').textContent=id?'Editar lançamento':'Novo lançamento';$('#entry-dialog').showModal();}
function updateEntryFields(){const f=$('#entry-form'),income=f.elements.kind.value==='income';$('#source-label').textContent=income?'Origem da receita':'Conta ou cartão';f.elements.source.placeholder=income?'Ex.: SkyTEM ou cliente do freelance':'Ex.: Nubank ou cartão Itaú';f.elements.source.setAttribute('list',income?'income-origins':'account-options');$('#income-account').classList.toggle('hidden',!income);f.elements.account.disabled=!income;updatePaymentFields();}
$('#entry-form [name="kind"]').addEventListener('change',updateEntryFields);
function openGoal(id){const f=$('#goal-form');f.reset();MoneyInput.reset(f);f.elements.id.value='';if(id){const g=state.goals.find(g=>g.id===id);for(const k of ['id','name','deadline'])f.elements[k].value=g[k];f.elements.target.value=MoneyInput.format(g.target);f.elements.saved.value=MoneyInput.format(g.saved)}$('#goal-dialog').showModal();}
function cents(value){return MoneyInput.parse(value)}
$('#entry-form').onsubmit=safe(async event=>{
 event.preventDefault();const f=event.target,values=Object.fromEntries(new FormData(f)),id=values.id||newId();
 const entry={id,description:values.description.trim(),kind:values.kind,cents:cents(values.amount),category:values.category.trim(),source:values.source.trim(),account:values.kind==='income'?values.account.trim():'',date:values.date,frequency:values.frequency||'once',end_date:values.end_date||null};
 if(entry.cents<=0)throw Error('O valor deve ser maior que zero.');
 if(entry.end_date&&entry.end_date<entry.date)throw Error('A data final deve ser posterior à inicial.');
 const split=values.payment_mode==='installments';
 let newEntries=[entry];
 if(split){
   if(values.id||entry.kind!=='expense'||!state.accounts.some(a=>a.name===entry.source&&a.type==='credit'))throw Error('Selecione um cartão cadastrado como cartão de crédito.');
   newEntries=await rustRequest({installments:{entry:{...entry,frequency:'once',end_date:null},count:Number(values.installment_count)}});
 }
 const next=structuredClone(state);next.entries=next.entries.filter(e=>e.id!==id);next.entries.push(...newEntries);await save(next);$('#entry-dialog').close();
});
$('#goal-form').onsubmit=safe(async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.target)),id=values.id||newId(),g={id,name:values.name.trim(),target:cents(values.target),saved:cents(values.saved),deadline:values.deadline};if(!g.target||g.saved>g.target)throw Error('Confira o objetivo e o valor já guardado.');const next=structuredClone(state);next.goals=next.goals.filter(g=>g.id!==id);next.goals.push(g);await save(next);$('#goal-dialog').close()});
function download(name,body,mime){const url=URL.createObjectURL(new Blob([body],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(){const cell=v=>'"'+String(v).replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';const rows=[['Data','Tipo','Descrição','Categoria','Origem da receita','Conta de recebimento','Conta ou cartão','Valor BRL','Repetição','Natureza'],...report.occurrences.map(o=>[o.date,o.entry.kind==='income'?'Receita':'Despesa',o.entry.description,o.entry.category,o.entry.kind==='income'?o.entry.source:'',o.entry.kind==='income'?(o.entry.account||''):'',o.entry.kind==='expense'?o.entry.source:'',(o.entry.cents/100).toFixed(2).replace('.',','),frequencies[o.entry.frequency],'Previsto (não conciliado)'])];download(`financa-dos-rapazes-${range()[0]}-${range()[1]}.csv`,'\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Relatório CSV exportado.');}
async function loadDemo(){if(state.entries.length||state.goals.length)throw Error('A demonstração só pode ser carregada em uma base vazia.');const date=new Date(),year=date.getFullYear(),month=String(date.getMonth()+1).padStart(2,'0'),day=n=>`${year}-${month}-${String(n).padStart(2,'0')}`,e=(description,kind,cents,category,source,n,frequency='monthly')=>({id:newId(),description,kind,cents,category,source,date:day(n),frequency,end_date:null});const deadline=new Date(year+1,date.getMonth()+8,1);const next={incomeSources:state.incomeSources||[],accounts:state.accounts||[],categories:state.categories,demo:true,entries:[{...e('Salário','income',850000,'Salário','SkyTEM',5),account:'Conta principal'},{...e('Projeto freelance','income',150000,'Trabalho extra','Cliente freelance',10,'once'),account:'Conta principal'},e('Aluguel e condomínio','expense',230000,'Moradia','Conta principal',8),e('Supermercado','expense',120000,'Alimentação','Cartão pessoal',12),e('Combustível','expense',48000,'Transporte','Cartão pessoal',14),e('Academia e saúde','expense',35000,'Saúde','Conta principal',16),e('Restaurantes e passeios','expense',65000,'Lazer','Cartão pessoal',18),e('Internet e serviços','expense',32000,'Outros','Conta principal',20)],goals:[{id:newId(),name:'Meu próximo carro',target:6000000,saved:1850000,deadline:iso(deadline)},{id:newId(),name:'Reserva de emergência',target:2500000,saved:1020000,deadline:iso(deadline)}]};await save(next);demo=true;anchor=new Date();period='month';view='dashboard';await refresh()}
document.addEventListener('click',safe(async event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.view){view=b.dataset.view;render()}if(b.dataset.period){if(b.dataset.period==='custom'&&!customRange){customRange=range();const f=$('#custom-period');f.elements.start.value=customRange[0];f.elements.end.value=customRange[1];}period=b.dataset.period;await refresh()}if(b.dataset.close)$('#'+b.dataset.close).close();if(b.id==='new-entry'){if(view==='incomeSources')openIncomeSource();else if(view==='accounts')openAccount();else if(view==='goals')openGoal();else openEntry()}if(b.id==='prev'||b.id==='next'){const sign=b.id==='prev'?-1:1;if(period==='month'){anchor.setDate(1);anchor.setMonth(anchor.getMonth()+sign)}else if(period==='year')anchor.setFullYear(anchor.getFullYear()+sign);else anchor.setDate(anchor.getDate()+sign*(period==='day'?1:7));await refresh()}if(b.dataset.editEntry)openEntry(b.dataset.editEntry);if(b.dataset.editGoal)openGoal(b.dataset.editGoal);for(const[k,list]of[['deleteEntry','entries'],['deleteGoal','goals']])if(b.dataset[k]&&confirm(list==='entries'?(state.entries.find(e=>e.id===b.dataset[k])?.frequency==='once'?'Excluir somente este lançamento ou parcela?':'Excluir este lançamento e todas as ocorrências da série?'):'Excluir esta meta?')){const next=structuredClone(state);next[list]=next[list].filter(x=>x.id!==b.dataset[k]);await save(next)}switch(b.dataset.action){case'new-entry':openEntry();break;case'new-goal':openGoal();break;case'entries':case'goals':view=b.dataset.action;render();break;case'csv':csv();break;case'backup':download(`financa-dos-rapazes-backup-${today()}.json`,JSON.stringify({schema:1,exported_at:new Date().toISOString(),...state},null,2),'application/json');break;case'restore':$('#restore-file').click();break;case'demo':await loadDemo();break;case'clear-demo':if(confirm('Excluir todos os registros desta base de demonstração? Alterações feitas nela também serão removidas.')){await save({entries:[],goals:[],accounts:state.accounts||[],incomeSources:state.incomeSources||[],categories:state.categories});demo=false;render()}break;}}));
document.addEventListener('input',e=>{if(e.target.id==='search'){filter=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
$('#restore-file').onchange=safe(async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>4_000_000)throw Error('Backup muito grande.');const data=JSON.parse(await file.text());if(data.schema!==1||!Array.isArray(data.entries)||!Array.isArray(data.goals))throw Error('Formato de backup incompatível.');if(confirm('Restaurar substitui todos os dados atuais. Você já exportou uma cópia?')){await save({entries:data.entries,goals:data.goals,accounts:validateAccounts(data.accounts||[]),incomeSources:IncomeSources.validate(data.incomeSources??[]),demo:!!data.demo,categories:Categories.validate(data.categories)});demo=!!state.demo;render()}});
(async()=>{try{state=await api('/api/state');state.accounts||=[];state.incomeSources=IncomeSources.validate(state.incomeSources??[]);demo=!!state.demo;await refresh()}catch(e){$('#content').innerHTML=`<div class="error-panel">Não foi possível carregar os dados: ${esc(e.message)}. Reinicie o aplicativo para tentar novamente.</div>`}})();

const accountTypes={checking:'Conta corrente',credit:'Cartão de crédito',benefit:'Cartão de benefícios',cash:'Dinheiro',other:'Outro'};
function validateAccounts(items){if(!Array.isArray(items)||items.length>1000)throw Error('Cadastro de contas inválido.');const ids=new Set(),names=new Set();for(const a of items){if(!a||typeof a.id!=='string'||!a.id||typeof a.name!=='string'||!a.name.trim()||a.name.length>120||!Object.hasOwn(accountTypes,a.type)||ids.has(a.id)||names.has(a.name.trim().toLocaleLowerCase()))throw Error('Cadastro de contas inválido ou duplicado.');ids.add(a.id);names.add(a.name.trim().toLocaleLowerCase())}return items}
function accounts(){return `<section class="card"><div class="card-head"><h2>Contas e cartões cadastrados</h2></div><p class="muted">Selecione um nome ao cadastrar uma despesa ou a conta de recebimento de uma receita.</p>${(state.accounts||[]).length?`<div class="table-wrap"><table><thead><tr><th>Nome</th><th>Tipo</th><th>Ações</th></tr></thead><tbody>${state.accounts.map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(accountTypes[a.type])}</td><td><div class="actions"><button data-edit-account="${esc(a.id)}">Editar</button><button data-delete-account="${esc(a.id)}">Excluir</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma conta ou cartão cadastrado.<br>Exemplos: Cartão Nubank, Cartão Flash e Conta corrente Nubank.</div>'}</section>`}
function updateAccountOptions(){$('#account-options').innerHTML=(state.accounts||[]).map(a=>`<option value="${esc(a.name)}">${esc(accountTypes[a.type])}</option>`).join('')}
function openAccount(id){const f=$('#account-form');f.reset();f.elements.id.value='';if(id){const a=state.accounts.find(a=>a.id===id);for(const k of ['id','name','type'])f.elements[k].value=a[k]}$('#account-title').textContent=id?'Editar conta ou cartão':'Nova conta ou cartão';$('#account-dialog').showModal()}
$('#account-form').onsubmit=safe(async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target)),a={id:v.id||newId(),name:v.name.trim(),type:v.type},next=structuredClone(state),old=(next.accounts||[]).find(x=>x.id===a.id);next.accounts=(next.accounts||[]).filter(x=>x.id!==a.id);next.accounts.push(a);validateAccounts(next.accounts);if(old&&old.name!==a.name)for(const entry of next.entries){if(entry.kind==='expense'&&entry.source===old.name)entry.source=a.name;if(entry.kind==='income'&&entry.account===old.name)entry.account=a.name}await save(next);$('#account-dialog').close()});
document.addEventListener('click',safe(async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.editAccount)openAccount(b.dataset.editAccount);if(b.dataset.deleteAccount&&confirm('Excluir este cadastro? Os lançamentos existentes manterão o nome salvo.')){const next=structuredClone(state);next.accounts=next.accounts.filter(a=>a.id!==b.dataset.deleteAccount);await save(next)}}));

function expenseSummary(){
 const {items,totals}=summarizeExpenses(report.occurrences,state.accounts||[]);
 const types={...accountTypes,unclassified:'Sem tipo cadastrado'};
 return `<section class="card full-card" id="expense-summary"><div class="card-head"><div><h2>Despesas por conta e cartão</h2><p>Valores previstos no período selecionado. Inclui somente as parcelas que vencem no período.</p></div></div>${items.length?`<div class="expense-types">${Object.entries(types).filter(([type])=>totals[type]).map(([type,label])=>`<div><span>${esc(label)}</span><strong>${money(totals[type])}</strong></div>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>Conta ou cartão</th><th>Tipo</th><th class="amount">Despesa prevista</th></tr></thead><tbody>${items.map(item=>`<tr><td>${esc(item.name)}</td><td>${esc(types[item.type]||types.unclassified)}</td><td class="amount">${money(item.cents)}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="2">Total do período</td><td class="amount"><b>${money(report.expense)}</b></td></tr></tfoot></table></div>${totals.unclassified?'<p class="muted">Para classificar os registros sem tipo, cadastre uma conta ou cartão com o mesmo nome usado no lançamento.</p>':''}`:'<div class="empty">Nenhuma despesa neste período.</div>'}</section>`;
}
let installmentPreviewVersion=0;
function updatePaymentFields(){
 const f=$('#entry-form'),income=f.elements.kind.value==='income',editing=!!f.elements.id.value;f.querySelector('.form-message')?.remove();
 $('#payment-mode-label').classList.toggle('hidden',income||editing);f.elements.payment_mode.disabled=income||editing;
 if(income||editing)f.elements.payment_mode.value='single';
 const split=f.elements.payment_mode.value==='installments';
 $('#installment-fields').classList.toggle('hidden',!split);f.elements.installment_count.disabled=!split;f.elements.installment_count.required=split;
 for(const name of ['frequency','end_date']){f.elements[name].disabled=split;f.elements[name].closest('label').classList.toggle('hidden',split)}
 $('#amount-label').textContent=split?'Valor total da compra (R$)':'Valor (R$)';$('#date-label').textContent=split?'Data da primeira parcela':'Data inicial';
 $('#entry-help').textContent=editing?'A edição altera somente este lançamento. Para recorrências, altera toda a série.':'Recorrências e parcelas são previsões. Esta versão ainda não concilia pagamentos.';
 updateInstallmentPreview();
}
async function updateInstallmentPreview(){
 const version=++installmentPreviewVersion,f=$('#entry-form'),target=$('#installment-preview');if(f.elements.payment_mode.value!=='installments')return;
 try{
  const count=Number(f.elements.installment_count.value),total=cents(f.elements.amount.value);if(!total||!f.elements.date.value){target.textContent='Preencha o valor total e a data para conferir as parcelas.';return}
  const parts=await rustRequest({installments:{count,entry:{id:'preview',description:'Compra',kind:'expense',cents:total,category:'Outros',source:'Cartão',account:'',date:f.elements.date.value,frequency:'once',end_date:null}}});
  if(version!==installmentPreviewVersion)return;
  target.textContent=`${parts.length} parcelas · total ${money(total)}. Primeira: ${money(parts[0].cents)} em ${human(parts[0].date)}. Última: ${money(parts.at(-1).cents)} em ${human(parts.at(-1).date)}. Centavos restantes são distribuídos nas primeiras parcelas.`;
 }catch(e){if(version===installmentPreviewVersion)target.textContent=e.message}
}
$('#entry-form [name="payment_mode"]').addEventListener('change',updatePaymentFields);
$('#entry-form').addEventListener('input',e=>{if(['amount','date','installment_count'].includes(e.target.name))updateInstallmentPreview()});

function incomeSources(){return `<section class="card"><div class="card-head"><h2>Fontes de receita cadastradas</h2></div><p class="muted">Escolha uma destas fontes no campo “Origem da receita” ao cadastrar um lançamento do tipo Receita.</p>${(state.incomeSources||[]).length?`<div class="table-wrap"><table><thead><tr><th>Fonte de receita</th><th>Ações</th></tr></thead><tbody>${state.incomeSources.map(source=>`<tr><td>${esc(source.name)}</td><td><div class="actions"><button data-edit-source="${esc(source.id)}">Editar</button><button data-delete-source="${esc(source.id)}">Excluir</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma fonte cadastrada.<br>Exemplos: salário da empresa, freelance, aluguel e rendimentos.</div>'}<p class="muted">As origens digitadas em lançamentos antigos continuam disponíveis. Renomear uma fonte atualiza as receitas associadas; excluir o cadastro preserva os lançamentos.</p></section>`}
function updateIncomeSourceOptions(){$('#income-origins').innerHTML=IncomeSources.options(state).map(name=>`<option value="${esc(name)}"></option>`).join('')}
function openIncomeSource(id){const f=$('#income-source-form');f.querySelector('.form-message')?.remove();f.reset();f.elements.id.value='';if(id){const source=state.incomeSources.find(s=>s.id===id);f.elements.id.value=source.id;f.elements.name.value=source.name}$('#income-source-title').textContent=id?'Editar fonte de receita':'Nova fonte de receita';$('#income-source-dialog').showModal()}
$('#income-source-form').onsubmit=safe(async e=>{e.preventDefault();const f=e.target;await save(IncomeSources.upsert(state,{id:f.elements.id.value||newId(),name:f.elements.name.value}));updateIncomeSourceOptions();$('#income-source-dialog').close()});
document.addEventListener('click',safe(async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.editSource)openIncomeSource(b.dataset.editSource);if(b.dataset.deleteSource&&confirm('Excluir esta fonte do cadastro? As receitas existentes serão preservadas.')){await save(IncomeSources.remove(state,b.dataset.deleteSource));updateIncomeSourceOptions()}}));

function profiles(info=GoogleProfiles.stateInfo()){
 const profile=info.profile;
 const date=value=>value?new Date(value).toLocaleString('pt-BR'):'Nenhum envio confirmado';
 return `${info.metadataError?'<div class="notice">O cadastro local de perfis está inválido. Os dados existentes foram preservados; o perfil local continua disponível.</div>':''}<section class="card settings-block"><div class="card-head"><h2>${profile?esc(profile.name):'Perfil local'}</h2><span class="tag">${info.connected?'GOOGLE CONECTADO':profile?'GOOGLE DESCONECTADO':'DADOS LOCAIS'}</span></div>${profile?`<p>${esc(profile.email)}</p>`:'<p>Os dados existentes permanecem no perfil local. Ao entrar com Google, será aberto um perfil separado.</p>'}<div class="notice">${esc(info.status||(!info.configured?'Configuração Google pendente. O login e o envio ao Drive ainda não estão habilitados.':'Entre com Google para ativar o salvamento no Drive.'))}</div><p>Última cópia confirmada: <strong>${esc(date(info.lastBackup))}</strong></p><button class="primary" data-profile-action="connect" ${info.busy||!info.configured?'disabled':''}>${info.connected?'Trocar conta Google':'Entrar com Google'}</button>${profile?`<button class="secondary" data-profile-action="sync" ${info.busy||!info.connected?'disabled':''}>Salvar / conferir Drive agora</button><button class="secondary" data-profile-action="history" ${info.busy||!info.connected?'disabled':''}>Cópias anteriores</button><button class="secondary" data-profile-action="import" ${info.busy?'disabled':''}>Copiar dados do perfil local</button><button class="secondary" data-profile-action="logout" ${info.busy?'disabled':''}>Sair para perfil local</button>`:''}${info.conflict?'<p class="notice">Existe outra versão no Drive. Consulte “Cópias anteriores” para restaurá-la ou mantenha os dados atuais como uma nova cópia. As cópias anteriores não serão apagadas.</p><button class="secondary" data-profile-action="keep-local">Manter minha versão e enviar</button>':''}<p class="muted">O Drive usa uma pasta privada do aplicativo. O envio automático funciona enquanto esta página está aberta e a sessão Google está válida. Sem conexão, os dados ficam pendentes neste navegador. Nenhum token é salvo no backup.</p></section>${info.history.length?`<section class="card settings-block full-card"><h2>Cópias no Google Drive</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Ação</th></tr></thead><tbody>${info.history.map(file=>`<tr><td>${esc(date(file.createdTime))}</td><td><button class="secondary" data-restore-cloud="${esc(file.id)}">Restaurar esta cópia</button></td></tr>`).join('')}</tbody></table></div></section>`:''}${info.profiles.length?`<section class="card settings-block full-card"><h2>Perfis neste navegador</h2><p class="muted">Conecte a conta Google correspondente para abrir seu perfil. As cópias locais não são criptografadas; proteja a sessão do seu computador.</p>${info.profiles.map(p=>`<div class="profile-item"><strong>${esc(p.name)}</strong><small>${esc(p.email)}</small><button class="secondary" data-open-profile="${esc(p.sub)}" ${info.busy?'disabled':''}>Entrar com esta conta</button></div>`).join('')}</section>`:''}<section class="card settings-block full-card"><h2>Configuração do aplicativo Google</h2><p>É necessário um Client ID OAuth do tipo Aplicativo da Web, com a API Google Drive habilitada e a origem <strong>https://jdantanna.github.io</strong> autorizada. O Client ID é público; nunca informe Client Secret ou senha.</p><form id="google-config-form"><label>Client ID OAuth<input name="client_id" value="${esc(GoogleProfiles.clientId())}" placeholder="…apps.googleusercontent.com" required autocomplete="off"></label><button class="secondary" type="submit">Salvar configuração Google</button></form></section>`;
}
function renderProfileStatus(info=GoogleProfiles.stateInfo()){const p=info.profile;$('#profile-initial').textContent=p?p.name.charAt(0).toUpperCase():'L';$('#profile-display').replaceChildren(document.createTextNode(p?p.name:'Perfil local'));const small=document.createElement('small');small.textContent=p?(info.connected?'Google conectado':'Google desconectado'):'Entrar com Google';$('#profile-display').append(small);$('#profile-cloud-status').textContent=info.status||(p?'Dados deste perfil no navegador':'Dados do perfil local neste navegador');$('#cloud-toolbar-status').textContent=info.busy?'● Operação no Google Drive…':info.connected&&info.head&&info.lastBackup&&!info.dirty&&info.status==='Cópia confirmada no Google Drive.'?'● Cópia confirmada no Drive':p?'● Drive: confira o status em Perfis':'● Salvo neste navegador';$('#storage-notice').textContent=p?`Perfil: ${p.name} · ${info.status||'Dados neste navegador. Reconecte o Google para salvar no Drive.'}`:'Perfil local · Dados neste navegador. Entre com Google em Perfis para ativar o Drive.';}
document.addEventListener('finance:cloud-status',()=>{if(view==='profiles')render();else renderProfileStatus()});
document.addEventListener('finance:profile-change',safe(async()=>{++refreshVersion;const profile=GoogleProfiles.store.active,epoch=GoogleProfiles.store.epoch;for(const d of document.querySelectorAll('dialog[open]'))d.close();const next=await api('/api/state');if(profile!==GoogleProfiles.store.active||epoch!==GoogleProfiles.store.epoch)return;state=next;state.accounts||=[];state.incomeSources||=[];demo=!!state.demo;filter='';view='profiles';await refresh()}));
document.addEventListener('submit',safe(async e=>{if(e.target.id==='google-config-form'){e.preventDefault();GoogleProfiles.configure(e.target.elements.client_id.value)}}));
document.addEventListener('click',safe(async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.openProfile){GoogleProfiles.connect(b.dataset.openProfile);return}if(b.dataset.restoreCloud){if(confirm('Restaurar esta cópia substitui os dados exibidos neste perfil. As cópias do Drive são preservadas. Continuar?'))await GoogleProfiles.restore(b.dataset.restoreCloud);return}switch(b.dataset.profileAction){case'connect':GoogleProfiles.connect();break;case'sync':await GoogleProfiles.synchronize();break;case'history':await GoogleProfiles.loadHistory();break;case'logout':GoogleProfiles.logout();break;case'import':if(confirm('Copiar os dados do perfil local para este perfil Google? Isso substituirá os dados exibidos e enviará a nova cópia ao Drive quando conectado.'))await GoogleProfiles.importLocal();break;case'keep-local':if(confirm('Enviar os dados deste navegador como nova versão no Drive, preservando as cópias anteriores?'))await GoogleProfiles.synchronize({preferLocal:true});break}}));


